import itertools

def is_diverse(flags):
    n = len(flags[0])
    for color in [0, 1]:
        adj = []
        for i in range(n):
            adj.append([j for j in range(n) if flags[i][j] == color])

        match = [-1] * n
        def can_match(u, visited):
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    if match[v] < 0 or can_match(match[v], visited):
                        match[v] = u
                        return True
            return False

        count = 0
        for i in range(n):
            visited = [False] * n
            if can_match(i, visited):
                count += 1
        if count == n:
            return True
    return False

def find_max_diverse_free(n):
    all_flags = list(itertools.product([0, 1], repeat=n))
    max_size = 0

    # Use backtracking to find the maximum diverse-free set
    def backtrack(index, current_set):
        nonlocal max_size
        if index == len(all_flags):
            max_size = max(max_size, len(current_set))
            return

        # Try including all_flags[index]
        flag = all_flags[index]
        new_set = current_set + [flag]
        is_still_free = True
        if len(new_set) >= n:
            # To optimize, we only need to check if any subset of size n 
            # containing the new flag is diverse.
            # Actually, it's even stronger: if ANY subset of size n 
            # in new_set is diverse, then it's not diverse-free.
            # But we only need to check subsets that include the new flag.
            for subset in itertools.combinations(new_set, n):
                if is_diverse(list(subset)):
                    is_still_free = False
                    break

        if is_still_free:
            backtrack(index + 1, new_set)

        # Try excluding all_flags[index]
        backtrack(index + 1, current_set)

    # This is still a bit slow, but for small n it should work.
    # Let's try a different approach for finding the max size.
    # A set S is diverse-free if NO subset of size n is diverse.

    # Let's try a greedy approach with some backtracking or just a simple search.
    def find_max_size_recursive(index, current_set):
        nonlocal max_size
        max_size = max(max_size, len(current_set))

        for i in range(index, len(all_flags)):
            flag = all_flags[i]
            new_set = current_set + [flag]
            is_still_free = True
            if len(new_set) >= n:
                for subset in itertools.combinations(new_set, n):
                    if is_diverse(list(subset)):
                        is_still_free = False
                        break

            if is_still_free:
                find_max_size_recursive(i + 1, new_set)

    find_max_size_recursive(0, [])
    return max_size + 1

for n in range(1, 5):
    print(f"n={n}, M={find_max_diverse_free(n)}")

